    ('seed-review-goma-pending', 'GOMA', 'seed-rev-res-goma-pending', 'seed-prop-goma-lakeside', 'seed-host-goma-lake', 'seed-guest-goma-2', 3, 'Comfortable villa, but the water pressure was low on the second morning.', 'PENDING', NULL, NULL, NULL, NULL, '2026-09-21T09:00:00Z', '2026-09-21T09:00:00Z'),
    ('seed-review-goma-pending-rating-only', 'GOMA', 'seed-rev-res-goma-pending-rating-only', 'seed-prop-goma-lakeside', 'seed-host-goma-lake', 'seed-guest-goma-5', 5, NULL, 'PENDING', NULL, NULL, NULL, NULL, '2026-09-23T09:00:00Z', '2026-09-23T09:00:00Z'),
